INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-moss-flush', 'door', 'The Moss Flush', 'Under the west lip of the snowfield the melt comes out in a sheet a finger deep and runs over a shelf of black rock before it goes over the edge, and where it runs the rock has grown a skin of moss, green enough to hurt after an hour of white. It is the only colour on the snowfield. It is cropped close all over, and the snow round its edge is trodden into a ring of small prints.', 0, 0, 'mountain', 0, 92, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moss-flush', 'east', 'the-upper-brim', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-brim', 'west', 'the-moss-flush', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-red-moss', 'door', 'The Red Moss', 'The rust slope runs out at the bottom into a hollow where the water off the stained run comes to rest, and the stones in it have grown a crust of moss and lichen the same red as everything else, so that you only see it is alive when you kneel. It is barely food. Something has been kneeling to it anyway: the crust is nibbled back in patches all over, and the patches are fresh.', 0, 0, 'mountain', 0, 99, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-moss', 'north', 'the-rust-slope', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rust-slope', 'south', 'the-red-moss', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cushion-ledge', 'door', 'The Cushion Ledge', 'A ledge off the north side of the step, out of the wind, and the rock under it is warm on its own account the way the ground behind you was. Cushion plants have taken the whole of it, tight green domes the size of a fist, packed edge to edge in the cracks where the warmth comes up. Nothing else on the ridge grows. These are grazed down to the rock on the outside of every cushion and nowhere else.', 0, 0, 'mountain', 0, 103, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cushion-ledge', 'south', 'the-first-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-step', 'north', 'the-cushion-ledge', NULL);
